-- =====================================================================
-- 7. MATERIALIZED VIEWS — Pre-aggregated for fast drill-down
-- =====================================================================

CREATE MATERIALIZED VIEW MV_METRIC_G1 AS
  SELECT
    FM_TYPE,
    FM_GROUP_1,
    FM_GROUP_1_ORDER,
    FM_PERIODE_GRAIN,
    FM_PERIODE_DATE,
    FM_PERIODE_LABEL,
    FM_SCENARIO,
    SUM(FM_DISPLAY_VALUE) AS MV_VALUE,
    COUNT(*) AS MV_ROW_COUNT
  FROM FACT_METRIC
  WHERE FM_IS_ACTIVE = TRUE
  GROUP BY 1,2,3,4,5,6,7;

CREATE UNIQUE INDEX IDX_MV_G1_PK ON MV_METRIC_G1
  (FM_TYPE, FM_GROUP_1, FM_PERIODE_GRAIN, FM_PERIODE_DATE, FM_SCENARIO);

CREATE MATERIALIZED VIEW MV_METRIC_G2 AS
  SELECT
    FM_TYPE,
    FM_GROUP_1,
    FM_GROUP_2,
    FM_GROUP_1_ORDER,
    FM_GROUP_2_ORDER,
    FM_PERIODE_GRAIN,
    FM_PERIODE_DATE,
    FM_PERIODE_LABEL,
    FM_SCENARIO,
    SUM(FM_DISPLAY_VALUE) AS MV_VALUE,
    COUNT(*) AS MV_ROW_COUNT
  FROM FACT_METRIC
  WHERE FM_IS_ACTIVE = TRUE AND FM_GROUP_2 IS NOT NULL
  GROUP BY 1,2,3,4,5,6,7,8,9;

CREATE UNIQUE INDEX IDX_MV_G2_PK ON MV_METRIC_G2
  (FM_TYPE, FM_GROUP_1, FM_GROUP_2, FM_PERIODE_GRAIN, FM_PERIODE_DATE, FM_SCENARIO);

-- Refresh function (called by ETL worker after data load)
CREATE OR REPLACE FUNCTION REFRESH_DASHBOARD_MVS()
RETURNS VOID AS $$
BEGIN
  REFRESH MATERIALIZED VIEW CONCURRENTLY MV_METRIC_G1;
  REFRESH MATERIALIZED VIEW CONCURRENTLY MV_METRIC_G2;
END;
$$ LANGUAGE plpgsql;

