SELECT 'FACT_METRIC total rows: ' || COUNT(*)::TEXT AS verification FROM FACT_METRIC;

-- Should return 2 (EBITDA, NET PROFIT)
SELECT 'Distinct GROUP_1: ' || STRING_AGG(DISTINCT FM_GROUP_1, ', ') AS verification FROM FACT_METRIC;

-- Should return 40 (months from 202301 to 202604)
SELECT 'Distinct periods: ' || COUNT(DISTINCT FM_PERIODE_LABEL)::TEXT AS verification FROM FACT_METRIC;

-- EBITDA total per month (sanity check vs Excel)
-- April 2026 should be approximately +1,015,881 USD
SELECT FM_PERIODE_LABEL, ROUND(SUM(FM_DISPLAY_VALUE), 2) AS ebitda_total
FROM FACT_METRIC
WHERE FM_GROUP_1 = 'EBITDA' AND FM_PERIODE_LABEL = '202604'
GROUP BY FM_PERIODE_LABEL;

-- Sample dashboard query — EBITDA waterfall data for April 2026
SELECT FM_GROUP_2, FM_GROUP_2_ORDER, ROUND(SUM(FM_DISPLAY_VALUE), 2) AS value
FROM FACT_METRIC
WHERE FM_GROUP_1 = 'EBITDA'
  AND FM_PERIODE_LABEL = '202604'
  AND FM_IS_ACTIVE = TRUE
GROUP BY FM_GROUP_2, FM_GROUP_2_ORDER
ORDER BY FM_GROUP_2_ORDER;

-- Verify materialized view freshness
SELECT 'MV_METRIC_G1 rows: ' || COUNT(*)::TEXT FROM MV_METRIC_G1;
SELECT 'MV_METRIC_G2 rows: ' || COUNT(*)::TEXT FROM MV_METRIC_G2;

-- Dashboard config check — should return 2 active dashboards
SELECT DC_DASHBOARD_CODE, DC_DASHBOARD_TITLE, DC_CHART_CONFIG->>'type' AS chart_type
FROM DASHBOARD_CONFIG WHERE DC_IS_ACTIVE = TRUE;
